"""
    Restructure transactions, so that each month every possible positin gets listed,
    even if its value is zero.

    transactions: ordered dict of transactions
    """
def restructure(transactions: Any) -> object {
    all_months = [tr.items() for (month, tr) in transactions.items()];
    all_groups_listed = [[x[0] for x in g] for g in all_months];
    all_groups = `set([item for sublist in all_groups_listed for item in sublist]);
    all_transactions = [];
    for (month, tr) in transactions.items() {
        months_transactions = {month: {}};
        for group in all_groups {
            value = tr.get(group, 0);
            months_transactions[month][group] = value;
        }
        all_transactions.append(months_transactions);
    }
    return all_transactions;
}

""" Convert a sexagesimal time to a formatted string.

    Parameters
    ----------
    hour, min, sec : int, float
    precision : int

    Returns
    -------
        String formatted HH:MM:SS.SSSSS

    """
def hms2stringTime(h: Any, m: Any, s: Any, precision: Any = 5) -> object {
    if ((h < 0) or (m < 0) or (s < 0)) {
        pm = '-';
    } else {
        pm = '+';
    }
    formString = '%s%02d:%02d:%0' + str((precision + 3)) + '.' + str(precision) + 'f';
    return (formString % (pm, abs(h), abs(m), abs(s)));
}

"""
    Converts textual description of number of likes to integer
    i.e. - '16.5k' -> 16,500
    """
def convertString(x: Any) -> object {
    string = str(x);
    if ('k' in string) {
        number = float(''.join(string.split('k')[0].split(','))) * 1000;
    } elif ('m' in string) {
        number = float(''.join(string.split('m')[0].split(','))) * 1000000;
    } else {
        number = float(''.join(string.split(',')));
    }
    return number;
}

