"""
    Formats a (0-6) weekday number as an abbreviated week day name, according to the current locale.
    For example: dayAbbrevFormat(0) -> "Sun".
    """
def dayAbbrevFormat(day: int) -> str {
    days = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
    return days[(day % 7)];
}
